{"input": "/opt/gsb-fleet/workspaces/inst-20/verification/evaluation-rounds/1/verify/inst-20-019/b/.audit-acceptance-2n14z13w/005-shared-complete-example.json", "submission": {"artifact": {"name": "Vault", "abi": "[{"name":"withdraw","type":"function","stateMutability":"payable"}]", "bytecode": "0x6080604052", "source": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Vault {
    mapping(address => uint256) private balances;

    function withdraw(uint256 amount) public {
        (bool sent, ) = msg.sender.call{value: amount}("");
        require(sent, "transfer failed");
        balances[msg.sender] -= amount;
